from __future__ import absolute_import
from taf.selenium.gnb.oam.coam.vdu import pages
import time


class BtsStatus(pages.BtsStatus):
    """
    The class corresponding to bts status page on selenium coam vdu webem, all operations under bts status
    page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self, driver, version):
        if not self._instance_dict:
            super(BtsStatus, self).__init__(driver, version)
            self._instance_dict.update({"Radio Modules Status": RadioModulesStatusPageV23R4(driver, version),
                                        "Site View": SiteViewStatusPageV23R4(driver, version)})


class RadioModulesStatusPageV23R4(pages.RadioModulesStatusPage):

    def __init__(self, driver, version):
        super(RadioModulesStatusPageV23R4, self).__init__(driver, version)
        self._view_panel = RadioModulesStatusPageViewPanelV23R4(driver, version)


class RadioModulesStatusPageViewPanelV23R4(pages.RadioModulesStatusPageViewPanel):

    def __init__(self, driver, version):
        super(RadioModulesStatusPageViewPanelV23R4, self).__init__(driver, version)

    def get_radio_status_info(self, radio_module, timeout):
        """
        Method for getting Radio Module info from details panel for corresponding radio module id

        :param radio_module: str, Radio name , default RMOD-1
        :param timeout: int, timeout for the element be available to click

        :return: dict, specific information of given Radio Module
        """
        self.wait_for_visibility(self.locator.RADIO_MODULES_XPATH.format(radio_module), timeout)
        self.click_enabled_element(self.locator.RADIO_MODULE_ID_XPATH.format(radio_module), timeout)
        if self.element_exists(self.locator.OPEN_DETAILS_PANEL_BUTTON, timeout):
            self.click_enabled_element(self.locator.OPEN_DETAILS_PANEL_BUTTON, timeout)
            time.sleep(1)
        self.click_enabled_element(self.locator.DETAILS_PANEL_OVERVIEW_BUTTON, timeout)
        detail_text = self.get_text(self.locator.DETAILS_PANEL_RADIO_DETAILS).splitlines()
        if self.element_exists(self.locator.CLOSE_DETAILS_PANEL_BUTTON, timeout):
            self.click_enabled_element(self.locator.CLOSE_DETAILS_PANEL_BUTTON, timeout)
            time.sleep(1)
        return self._parse_status_info_from_details_panel(detail_text)

    def _parse_status_info_from_details_panel(self, detail_text):
        """
        This keyword is for getting all the details of the radio module from the details panel and parsing it into dict

        :return: a dict of information collected for Radio module from detail panel
        """
        radio_info = {}
        for i in range(0, len(detail_text)):
            if ':' in detail_text[i]:
                radio_info.update({detail_text[i].split(":")[0].strip(): detail_text[i + 1].strip()})
            elif "Antenna ports" in detail_text[i]:
                radio_info.update({detail_text[i].strip(): detail_text[i + 1].strip()})
        return radio_info


class SiteViewStatusPageV23R4(pages.SiteViewStatusPage):
    """
    All operations on Site View Modules Status page will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['shield-check', 'Site View']

    def __init__(self, driver, version):
        super(SiteViewStatusPageV23R4, self).__init__(driver, version)
        self._view_panel = SiteViewStatusPageViewPanelV23R4(driver, version)

    def reset_ran_nic(self, object_name, graceful_cell_shutdown, timeout):
        """
        This keyword will reset ran nic is applicable from 23r4 onwards.

        :param object_name: str, (optional) object name of the ran nic. Default value is 'RNICMOD_R-1'
        :param graceful_cell_shutdown: str, (optional) default value is "False".If graceful cell shutdown is needed
                                      then pass graceful_cell_shutdown=True
        :param timeout: int, timeout for the element be available to click

        :return: str, Status of the reset ran nic 'RNICMOD_R-1 reset operation finished' or
                      'RNICMOD_R-1 reset operation failed'
        """
        return self._view_panel.reset_ran_nic(object_name, graceful_cell_shutdown, timeout)


class SiteViewStatusPageViewPanelV23R4(pages.SiteViewStatusPageViewPanel):
    def __init__(self, driver, version):
        super(SiteViewStatusPageViewPanelV23R4, self).__init__(driver, version)

    def reset_ran_nic(self, object_name, graceful_cell_shutdown, timeout):
        """
        This keyword will reset ran nic is applicable from 23r4 onwards.

        :param object_name: str, (optional) object name of the ran nic. Default value is 'RNICMOD_R-1'
        :param graceful_cell_shutdown: str, (optional) default value is "False".If graceful cell shutdown is needed
                                      then pass graceful_cell_shutdown=True
        :param timeout: int, timeout for the element be available to click

        :return: str, Status of the reset ran nic 'RNICMOD_R-1 reset operation finished' or
                      'RNICMOD_R-1 reset operation failed'
        """
        self.click_enabled_element(self.locator.RAN_NIC_BUTTON.format(object_name), timeout)
        if self.element_exists(self.locator.OPEN_DETAILS_PANEL_BUTTON, timeout):
            self.click_enabled_element(self.locator.OPEN_DETAILS_PANEL_BUTTON, timeout)
            time.sleep(1)
        self.click_enabled_element(self.locator.RESET_RAN_NIC_BUTTON, timeout)
        if graceful_cell_shutdown:
            self.click_enabled_element(self.locator.GRACEFUL_SHUTDOWN_BUTTON, timeout)
        self.click_enabled_element(self.locator.OK_BUTTON_XPATH, timeout)
        self.wait_for_visibility(self.locator.LOCK_UNLOCK_RESET_OPERATION_STARTED_LABEL.format('reset'), timeout)
        reset_ran_nic_status = self.get_text(self.locator.OPERATION_STATUS_LABEL_XPATH, timeout)
        if self.element_exists(self.locator.CLOSE_DETAILS_PANEL_BUTTON, timeout):
            self.click_enabled_element(self.locator.CLOSE_DETAILS_PANEL_BUTTON, timeout)
            time.sleep(1)
        return reset_ran_nic_status
